import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"41、【损】 兑下艮上","description":"温公易说 - 41、【损】 兑下艮上","frontmatter":{"title":"41、【损】 兑下艮上","description":"温公易说 - 41、【损】 兑下艮上"},"headers":[],"relativePath":"zh/classics/wengong/042.md","filePath":"zh/classics/wengong/042.md"}'),n={name:"zh/classics/wengong/042.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_41、【损】-兑下艮上" tabindex="-1">41、【损】 兑下艮上 <a class="header-anchor" href="#_41、【损】-兑下艮上" aria-label="Permalink to “41、【损】 兑下艮上”">​</a></h1><p>损益之名以内为主者也，内为已，外为彼。</p><h3 id="彖曰-损-损下益上-其道上行。损而有孚-元吉-无咎-可贞。利有攸往。曷之用-二簋-可用享。二簋-应有时。损刚益柔-有时损益盈虚-与时偕行。" tabindex="-1">彖曰：损，损下益上，其道上行。损而有孚，元吉，无咎，可贞。利有攸往。曷之用？二簋，可用享。二簋，应有时。损刚益柔，有时损益盈虚，与时偕行。 <a class="header-anchor" href="#彖曰-损-损下益上-其道上行。损而有孚-元吉-无咎-可贞。利有攸往。曷之用-二簋-可用享。二簋-应有时。损刚益柔-有时损益盈虚-与时偕行。" aria-label="Permalink to “彖曰：损，损下益上，其道上行。损而有孚，元吉，无咎，可贞。利有攸往。曷之用？二簋，可用享。二簋，应有时。损刚益柔，有时损益盈虚，与时偕行。”">​</a></h3><h3 id="象曰-山下有泽-损。君子以惩忿窒欲。" tabindex="-1">象曰：山下有泽，损。君子以惩忿窒欲。 <a class="header-anchor" href="#象曰-山下有泽-损。君子以惩忿窒欲。" aria-label="Permalink to “象曰：山下有泽，损。君子以惩忿窒欲。”">​</a></h3><h3 id="初九-已事遄往-无咎。酌损之-象曰-已事遄往-尚合志也。" tabindex="-1">初九：已事遄往，无咎。酌损之 象曰：已事遄往，尚合志也。 <a class="header-anchor" href="#初九-已事遄往-无咎。酌损之-象曰-已事遄往-尚合志也。" aria-label="Permalink to “初九：已事遄往，无咎。酌损之 象曰：已事遄往，尚合志也。”">​</a></h3><h3 id="九二-利贞-征凶。弗损益之-象曰-九二利贞-中以为志也。" tabindex="-1">九二：利贞，征凶。弗损益之 象曰：九二利贞，中以为志也。 <a class="header-anchor" href="#九二-利贞-征凶。弗损益之-象曰-九二利贞-中以为志也。" aria-label="Permalink to “九二：利贞，征凶。弗损益之 象曰：九二利贞，中以为志也。”">​</a></h3><h3 id="六三-三人行则损-一人行则得其友-象曰-一人行-三则疑也。" tabindex="-1">六三：三人行则损，一人行则得其友 象曰：一人行，三则疑也。 <a class="header-anchor" href="#六三-三人行则损-一人行则得其友-象曰-一人行-三则疑也。" aria-label="Permalink to “六三：三人行则损，一人行则得其友 象曰：一人行，三则疑也。”">​</a></h3><h3 id="六四-损其疾-使遄有喜-无咎-象曰-损其疾-亦可喜也。" tabindex="-1">六四：损其疾，使遄有喜，无咎 象曰：损其疾，亦可喜也。 <a class="header-anchor" href="#六四-损其疾-使遄有喜-无咎-象曰-损其疾-亦可喜也。" aria-label="Permalink to “六四：损其疾，使遄有喜，无咎 象曰：损其疾，亦可喜也。”">​</a></h3><h3 id="六五-或益之-十朋之龟-弗克违-元吉-象曰-六五元吉-自上佑也。" tabindex="-1">六五：或益之，十朋之龟，弗克违，元吉 象曰：六五元吉，自上佑也。 <a class="header-anchor" href="#六五-或益之-十朋之龟-弗克违-元吉-象曰-六五元吉-自上佑也。" aria-label="Permalink to “六五：或益之，十朋之龟，弗克违，元吉 象曰：六五元吉，自上佑也。”">​</a></h3><h3 id="上九-弗损益之-无咎-贞吉。利有攸往-得臣无家-象曰-弗损益之-大得志也。" tabindex="-1">上九：弗损益之，无咎，贞吉。利有攸往，得臣无家 象曰：弗损益之，大得志也。 <a class="header-anchor" href="#上九-弗损益之-无咎-贞吉。利有攸往-得臣无家-象曰-弗损益之-大得志也。" aria-label="Permalink to “上九：弗损益之，无咎，贞吉。利有攸往，得臣无家 象曰：弗损益之，大得志也。”">​</a></h3>',10)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
